"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["23703"],{52039(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.item_formulario.fato_nao_coletavel","status":422,"titulo":"O fato do item n\xe3o \xe9 colet\xe1vel num campo"},"descricao":{"codigo":"uniplus.item_formulario.fato_nao_coletavel","requisitos":["UNI-REQ-0143","UNI-REQ-0146"],"oQueAconteceu":["O fato existe no cat\xe1logo, mas n\xe3o pode ser coletado no campo em que foi posto. \xc9 colet\xe1vel o fato declarado, respondido num campo de formul\xe1rio, do pr\xf3prio candidato: o fato derivado por regra e o calculado pelo sistema n\xe3o s\xe3o respondidos, mas obtidos (UNI-REQ-0143), e o fato de membro de grupo s\xf3 existe dentro de um grupo repet\xedvel, onde cada ocorr\xeancia responde o seu (UNI-REQ-0146). A mensagem diz qual \xe9 a situa\xe7\xe3o:","- no item do formul\xe1rio: \\"O fato \'`{c\xf3digo\\\\}`\' n\xe3o \xe9 colet\xe1vel num campo: s\xf3 o fato declarado do pr\xf3prio candidato \xe9 respondido no formul\xe1rio \u2014 derivados, calculados e fatos de membro de grupo n\xe3o.\\";\\n- no campo de um grupo: \\"O fato \'`{c\xf3digo\\\\}`\' n\xe3o \xe9 colet\xe1vel num campo do grupo: s\xf3 o fato declarado de membro de grupo \xe9 respondido em cada ocorr\xeancia \u2014 fatos do candidato, derivados e calculados n\xe3o.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `itens[i].fatoCodigo` ou `grupos[g].subitens[j].fatoCodigo`; nos modelos de formul\xe1rio o `field` come\xe7a por `conteudo.`, e o pressuposto que nomeia um fato n\xe3o colet\xe1vel \xe9 recusado em `conteudo.pressupostos[i]`. O item cuja forma b\xe1sica j\xe1 foi recusada n\xe3o chega a esta confer\xeancia. Nada \xe9 gravado.","Na aplica\xe7\xe3o de um modelo ao processo, o item ou o grupo cujo fato deixou de ser colet\xe1vel depois da composi\xe7\xe3o do modelo n\xe3o \xe9 recusado: sai da c\xf3pia e volta no relat\xf3rio da aplica\xe7\xe3o, entre as partes descartadas. Na atualiza\xe7\xe3o de um modelo, um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Coloque no item do formul\xe1rio s\xf3 um fato declarado do pr\xf3prio candidato, e no campo de um grupo s\xf3 um fato declarado de membro de grupo. O fato derivado ou calculado chega \xe0s regras do formul\xe1rio por cita\xe7\xe3o, e n\xe3o por um campo."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Item formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);